/* eslint-disable no-undef */
import { Component, Element, Event, EventEmitter, h, Host, Listen, Method, Prop, State, Watch } from '@stencil/core';
import { FormDataEvent, LimitedSeverity } from '../../types';

/**
 * @nativeEvent click - dispatched when radio button was clicked => 'event.target.value' delivers the value of the clicked radio button
 * @nativeEvent change - dispatched when option has changed => 'event.target.value' delivers the value of the selected radio button
 *
 * @slot description - named slot 'description', any HTML content is allowed.
 */
@Component({
  tag: 'groupui-radio-group',
  styleUrl: 'radio-group.scss',
  shadow: true,
})
export class RadioGroup {
  /**
   * deactivates the whole radio-group
   */
  @Prop({ reflect: true }) readonly disabled: boolean = false;

  /**
   * value of the selected radio-button in this group
   */
  @Prop({ reflect: true, mutable: true }) value: string;

  /**
   * name of the radio-group to support forms
   */
  @Prop({ reflect: true }) readonly name: string;

  /**
   * severity of the radio-group
   */
  @Prop({ reflect: true, mutable: true }) severity: LimitedSeverity;

  /**
   * specifies that an option must be selected before submitting the form
   */
  @Prop({ reflect: true }) readonly required: boolean = false;

  /**
   * returns the element's current validityState state (readonly value)
   */
  @Prop({ reflect: false, mutable: true }) validity: ValidityState;

  /**
   * disable internal validation
   */
  @Prop({ reflect: true }) readonly noValidation: boolean = false;

  /**
   * for react user only - use this instead of the native change event
   */
  @Event({ bubbles: false }) groupuiChange: EventEmitter<void>;

  /**
   * is dispatched when the value is invalid
   */
  @Event({ bubbles: false }) groupuiInvalid: EventEmitter<ValidityState>;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @Listen('click')
  handleClick(event) {
    const closestRadioButton = event.target && event.target.closest('groupui-radio-button');
    if (
      !closestRadioButton ||
      this.disabled ||
      this.checkedElement === closestRadioButton ||
      closestRadioButton.disabled
    ) {
      return;
    }
    this.value = closestRadioButton.value;
  }

  /**
   * function to trigger component validation manually
   */
  @Method()
  async validate() {
    this.updateValidityState({ force: true });
  }

  @Element() host: HTMLElement;

  @State() checkedElement: HTMLGroupuiRadioButtonElement;

  @State() validityState: ValidityState;

  componentWillLoad() {
    this.initCheckedValue();
    this.validity = this.getValidity();
    this.updateRadioButtonDisabledInitially();
    this.updateRadioButtonSeverity();
    this.initFormsHandling();
  }

  componentDidLoad() {
    this.getRadioButtons().forEach((radioButton) => {
      radioButton.hasAttribute('autofocus') && radioButton.getAttribute('autofocus') !== 'false' && radioButton.focus();
    });
    this.groupuiDidLoad.emit();
  }

  private getRadioButtons(): HTMLGroupuiRadioButtonElement[] {
    return Array.from(this.host.querySelectorAll('groupui-radio-button'));
  }

  private updateRadioButtonDisabledInitially() {
    if (this.disabled) {
      this.getRadioButtons().forEach((radioButton) => radioButton.setAttribute('disabled', ''));
    }
  }

  private initCheckedValue() {
    this.checkedElement = this.getRadioButtons().find((radioButton) => radioButton.hasAttribute('checked'));

    if (!this.checkedElement && this.value) {
      this.checkRadioButton(this.value);
    }

    if (this.checkedElement) {
      this.value = this.getValueOfRadioButton(this.checkedElement);
    } else {
      this.value = undefined;
    }
  }

  private initFormsHandling() {
    if (this.name === undefined) return;

    const form = this.host.closest('form');
    if (form == null) return;

    form.addEventListener('formdata', (event: FormDataEvent) => {
      event.formData.append(this.name, this.value);
    });

    form.addEventListener('submit', (event) => {
      this.updateValidityState();
      if (!this.validityState || !this.validityState.valid) {
        event.preventDefault();
      }
    });
  }

  @Watch('disabled')
  onDisabledChanged() {
    if (this.disabled) {
      this.getRadioButtons().forEach((radioButton) => radioButton.setAttribute('disabled', ''));
    } else {
      this.getRadioButtons().forEach((radioButton) => radioButton.removeAttribute('disabled'));
    }
  }

  @Watch('severity')
  private updateRadioButtonSeverity() {
    if (this.severity) {
      this.getRadioButtons().forEach((radioButton) => radioButton.setAttribute('severity', this.severity));
    }
  }

  private checkRadioButton(value: string) {
    this.getRadioButtons().forEach((radioButton) => {
      if (radioButton.value === value) {
        radioButton.checked = true;
        this.checkedElement = radioButton;
      } else {
        radioButton.removeAttribute('checked');
      }
    });
  }

  @Watch('value')
  onValueChanged(newValue: string, oldValue: string) {
    if (newValue !== oldValue) {
      this.checkRadioButton(newValue);
      this.host.dispatchEvent(new window.Event('change'));
      this.groupuiChange.emit();
    }
  }

  private getValueOfRadioButton(radioButton: HTMLGroupuiRadioButtonElement): string {
    if (!radioButton.value) {
      radioButton.value = Math.random().toString(36).substring(7);
    }
    return radioButton.value;
  }

  @Watch('validityState')
  onValidityStateChanged() {
    this.severity = this.validityState && this.validityState.valid ? 'none' : 'danger';
    if (!this.validityState || !this.validityState.valid) {
      this.dispatchInvalidEvent();
    }
  }

  private dispatchInvalidEvent() {
    this.host.dispatchEvent(new window.Event('invalid'));
    this.groupuiInvalid.emit(this.validityState);
  }

  private updateValidityState({ force = false }: { force?: boolean } = {}) {
    const validity = this.getValidity();
    this.validity = validity;

    if (!force && this.noValidation) return;
    this.validityState = validity;
  }

  private getValidity() {
    return {
      badInput: false,
      customError: false,
      patternMismatch: false,
      rangeOverflow: false,
      rangeUnderflow: false,
      stepMismatch: false,
      tooLong: false,
      tooShort: false,
      typeMismatch: false,
      valid: this.isValid(),
      valueMissing: !this.validateRequired(),
    };
  }

  private isValid() {
    return this.validateRequired();
  }

  private validateRequired(): boolean {
    if (this.required) {
      return !!this.value;
    }
    return true;
  }

  render() {
    return (
      <Host role="radiogroup">
        <slot />
        <slot name="description" />
      </Host>
    );
  }
}
